I wrote the tests first for a hemodynamics helper in our physiology-teaching repo (educational, synthetic values). Here is the complete test file. Save it as tests/test_hemo.py verbatim, run it to see failures, then implement hemo.py until green without modifying the tests.

import pytest
from hemo import map_mmhg, pulse_pressure, shock_index

def test_map():
    assert map_mmhg(120, 80) == pytest.approx(93.33, abs=0.01)

def test_map_rejects_inverted():
    with pytest.raises(ValueError):
        map_mmhg(80, 120)

def test_pulse_pressure():
    assert pulse_pressure(120, 80) == 40

def test_shock_index():
    assert shock_index(100, 120) == pytest.approx(0.83, abs=0.01)

def test_shock_index_flags():
    assert shock_index(130, 100, classify=True) == (1.3, "elevated")
    assert shock_index(60, 120, classify=True) == (0.5, "normal")

def test_zero_sbp_rejected():
    with pytest.raises(ValueError):
        shock_index(100, 0)

Shock index is heart_rate / sbp, elevated when >= 0.9. Show the failing run first, then the passing run.

