def _validate_pressure(sbp: float, dbp: float) -> None:
    if sbp <= 0:
        raise ValueError("systolic pressure must be positive")
    if dbp <= 0:
        raise ValueError("diastolic pressure must be positive")
    if dbp > sbp:
        raise ValueError("diastolic pressure cannot exceed systolic pressure")


def map_mmhg(sbp: float, dbp: float) -> float:
    """Mean arterial pressure (mmHg): DBP + 1/3 * (SBP - DBP)."""
    _validate_pressure(sbp, dbp)
    return dbp + (sbp - dbp) / 3


def pulse_pressure(sbp: float, dbp: float) -> int:
    """Pulse pressure (mmHg): SBP - DBP."""
    _validate_pressure(sbp, dbp)
    return sbp - dbp


def shock_index(heart_rate: float, sbp: float, classify: bool = False):
    """Shock index: heart rate / SBP. Elevated when >= 0.9.

    Returns just the index as a float, or a (index, class) tuple
    when classify=True.
    """
    if heart_rate <= 0:
        raise ValueError("heart rate must be positive")
    if sbp <= 0:
        raise ValueError("systolic pressure must be positive")

    index = heart_rate / sbp
    if not classify:
        return index
    return index, "elevated" if index >= 0.9 else "normal"
